def is_multiply_prime(a):
    if a < 2:
        return False

    prime_factors = []
    # Check divisibility by 2
    if a % 2 == 0:
        prime_factors.append(2)
        while a % 2 == 0:
            a //= 2

    # Check divisibility by odd numbers
    for num in range(3, int(a**0.5) + 1, 2):
        while a % num == 0:
            prime_factors.append(num)
            a //= num

    # If there are more than 3 prime factors, we have overpartitioning
    if len(prime_factors) > 3:
        return False

    # Count unique prime factors
    unique_prime_factors = set(prime_factors)
    return len(unique_prime_factors) == 3
