def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1
    elif n == 2:
        return 20
    else:
        start_with_1 = 10 ** (n - 1) * 2
        end_with_1 = 10 ** (n - 1) * 2
        if n % 2 == 1:
            middle_start_with_1 = 10 ** ((n - 1) // 2) * 2
        else:
            middle_start_with_1 = 9 * 10 ** ((n - 1) // 2 - 1) * 2
        return start_with_1 + end_with_1 - middle_start_with_1
