def sum_of_digits_of_largest_prime(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.

    Args:
    lst (list): A list of integers.

    Returns:
    int: The sum of the digits of the largest prime value found in the list.
    """
    max_prime_value = -float('inf')
    digit_sum = 0

    for num in lst:
        # Check if the number is prime
        if num > 1:
            for i in range(2, num):
                if (num % i) == 0:
                    break
            else:
                # If the number is prime, update max_prime_value
                if num > max_prime_value:
                    max_prime_value = num

    # Check if there was a prime number found
    if max_prime_value == -float('inf'):
        return 0

    # Calculate the sum of the digits of the largest prime number
    while max_prime_value:
        digit_sum += max_prime_value % 10
        max_prime_value //= 10

    return digit_sum
