def move_one_ball(arr):
    # If the array is empty, return True
    if not arr:
        return True

    length = len(arr)
    if length == 1:
        return True

    count_dup = 0
    for i in range(length):
        if arr[i] == arr[0]:
            count_dup += 1

    # If there are duplicates at the start and mid of the array, 
    # it is not possible to get a sorted array by performing right shift operations.
    if count_dup >= 2:
        return False

    # Check a permutation ending at i is sorted by performing right shift operations
    for i in range(1, length - 1):
        for j in range(i + 1, length):
            if arr[j] < arr[j - 1]:
                return False

    return True

