from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dp = [[[float('inf')] * (k + 1) for _ in range(n)] for _ in range(n)]
    min_list = [[[[] for _ in range(k + 1)] for _ in range(n)] for _ in range(n)]

    for j in range(n):
        for i in range(n):
            dp[j][i][1] = (grid[i][j], (i, j))

    for h in range(2, k + 1):
        for j in range(n):
            for i in range(n):
                for d in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    dj, di = d
                    if i + dj >= 0 and i + dj < n and j + di >= 0 and j + di < n:
                        next_val = grid[i + dj][j + di]
                        next_obj = dp[i + dj][j + di][h - 1]
                        next_val_vec = next_obj[0]
                        cur_idx = h - 1
                        next_idx = h
                        if cur_idx < len(next_val_vec) and next_idx < len(next_val) and dp[i][j][h - 1][cur_idx] + 1 < dp[i + dj][j + di][h][next_idx]:
                            dp[i][j][h][next_idx] = dp[i][j][h - 1][cur_idx] + 1
                            min_list[i][j][h][next_idx] = next_obj[:cur_idx] + [next_val] + next_obj[cur_idx:]

    ans = []
    for obj in range(1, k + 1):
        ans = min(ans, min_list[0][0][obj][0])

    return ans
