import numpy as np

def do_algebra(operator, operand):
    # Check if operands are valid
    if len(operand) < 2:
        raise ValueError("Operand must have at least two operands.")

    # Decode operator list to Python arithmetic operators and operands
    decoded_operator = []
    for op in operator:
        if op == "+":
            decoded_operator.append(np.add)
        elif op == "-":
            decoded_operator.append(np.subtract)
        elif op == "*":
            decoded_operator.append(np.multiply)
        elif op == "//":
            decoded_operator.append(np.floor_divide)
        elif op == "**":
            decoded_operator.append(np.power)

    # Perform arithmetic operations
    result = decoded_operator[0](operand[0], operand[1])
    for i in range(2, len(operand)):
        result = decoded_operator[i](result, operand[i])

    return result
